{
  "name": "wlan_attach",
  "confidence": "medium",
  "docstring": "Initializes WLAN attach contexts by clearing per-instance state, populating 1024-entry descriptor/address tables, linking kernel state, and programming primary/secondary configuration blocks with chip ID, clock divider, and buffer counts.",
  "subsystem": "wlan",
