    "v7": "desc_table_param",
    "v8": "list_head",
    "v9": "primary_cfg",
    "v10": "cfg_default",
    "v11": "clk_div",
    "v12": "secondary_cfg",
    "v13": "cfg_param",
    "v15": "desc_index",
    "v16": "desc_addr",
    "v17": "desc_entry_ptr",
    "v18": "desc_entry_value",
    "result": "clk_div"
  },
  "struct_hints": [
    {
      "offset": 28,
      "meaning": "pointer to per-context descriptor/address table"
    },
    {
      "offset": 32,
      "meaning": "pointer to per-context control block"
    },
    {
      "offset": 53,
      "meaning": "attach/skip flag checked when not forcing initialization"
    },
    {
      "offset": 24,
      "meaning": "control-block field storing pointer to descriptor table"
    },
    {
      "offset": 4,
      "meaning": "chip-info-derived configuration value"
    },
    {
      "offset": 8,
      "meaning": "clock divider value"
    },
    {
      "offset": 16,
      "meaning": "base/default configuration parameter"
    },
    {
      "offset": 20,
      "meaning": "entry count; 1024 for primary block, 4 for secondary block"
    }
  ]
}
